header('Cache-Control: no-store, private');sessionOpen();$c=customer();$return=(string)($_GET['return']??'/account');if(!preg_match('~^/(cart|booking)(\?|$)~',$return))$return='/account';
if($path==='/account/verify'){customerSchema();$token=hash('sha256',(string)($_GET['token']??''));$r=sql('SELECT customer FROM customer_tokens WHERE token=? AND purpose=? AND expires>?',[$token,'verify',time()])->fetchColumn();if($r){sql('UPDATE customers SET verified=1 WHERE id=?',[$r]);sql('DELETE FROM customer_tokens WHERE token=?',[$token]);}$body='<section class="container section account-empty"><h1>'.($r?'Email verified.':'This link has expired.').'</h1><p>'.($r?'Your email address is now verified.':'Request a fresh verification email from your account.').'</p><a class="button" href="/account">Go to my account</a></section>';renderPage('Verify email | Desert Sky Tourism','Verify your customer email address.',$body,[],true);exit;}
if(in_array($path,['/account/sign-in','/account/sign-up','/account/forgot','/account/reset'])){if($c&&in_array($path,['/account/sign-in','/account/sign-up'])){header('Location: '.$return);exit;}$signup=$path==='/account/sign-up';$forgot=$path==='/account/forgot';$reset=$path==='/account/reset';$title=$signup?'Your next chapter starts here.':($forgot?'Let’s get you back in.':($reset?'A fresh start. A new password.':'Welcome back, explorer.'));ob_start();?><section class="customer-auth container"><div class="auth-photo"><img src="/assets/dubai-dunes-hero.webp" alt="Sunlit sand dunes in the Dubai desert" width="1200" height="1500"><div><span class="eyebrow">DESERT SKY TOURISM</span><h2>Less ordinary.<br>More adventure.</h2><p>Your experiences, your plans, your memories — all in one place.</p></div></div><div class="auth-content"><a href="/" class="text-link">← Back to exploring</a><span class="eyebrow">Your travel account</span><h1><?=esc($title)?></h1><p><?=$signup?'Save your paid bookings and manage your travel plans.':($forgot?'Enter your account email to request a secure recovery link.':($reset?'Choose a password of at least 12 characters.':'Sign in to see your paid bookings and upcoming experiences.'))?></p><form data-customer-form="<?=$signup?'register':($forgot?'forgot':($reset?'reset':'login'))?>" data-return="<?=esc($return)?>"><?php if($signup):?><label>Your full name<input name="name" autocomplete="name" required maxlength="150"></label><?php endif;if(!$reset):?><label>Email address<input name="email" type="email" autocomplete="email" required maxlength="254"></label><?php endif;if(!$forgot):?><label><?=$reset?'New password':'Password'?><input name="password" type="password" autocomplete="<?=$signup||$reset?'new-password':'current-password'?>" <?=$signup||$reset?'minlength="12"':''?> maxlength="200" required><small><?=$signup||$reset?'At least 12 characters. Password managers and paste are supported.':''?></small></label><?php endif;if($reset):?><input name="token" type="hidden" value="<?=esc($_GET['token']??'')?>"><?php endif;if($signup):?><label class="terms-checkbox"><input name="acceptedTerms" type="checkbox" required><span>I agree to the <a href="/terms" target="_blank" rel="noopener">terms</a> and <a href="/privacy" target="_blank" rel="noopener">privacy policy</a>.</span></label><?php endif;?><button class="button full" type="submit"><?=$signup?'Create my account':($forgot?'Send recovery link':($reset?'Save new password':'Sign in'))?> <?=icon()?></button><div class="form-message" role="status" aria-live="polite"></div></form><?php if(!$forgot&&!$reset):?><p class="auth-switch"><?=$signup?'Already have an account?':'New to Desert Sky?'?> <a href="/account/<?=$signup?'sign-in':'sign-up'?>?return=<?=rawurlencode($return)?>"><?=$signup?'Sign in':'Create an account'?></a></p><?php if(!$signup):?><a href="/account/forgot" class="text-link">Forgot your password?</a><?php endif;else:?><a href="/account/sign-in" class="text-link">Back to sign in</a><?php endif;?></div></section><?php renderPage($signup?'Create an account | Desert Sky Tourism':'Customer account | Desert Sky Tourism','Your Desert Sky customer account and travel plans.',ob_get_clean(),[],true);exit;}
if($path==='/account'){if(!$c){header('Location: /account/sign-in');exit;}$bookings=customerBookings($c['id']);ob_start();?><section class="account-banner"><div class="container"><span class="eyebrow">Your personal travel space</span><h1>Hello, <?=esc(explode(' ',$c['name'])[0])?>.<br>Where to next?</h1><p>Your paid bookings, all in one place.</p><a class="button button-yellow" href="/tours">Find my next adventure <?=icon()?></a></div></section><section class="container section customer-account"><aside class="account-profile"><span class="profile-avatar"><?=esc(mb_substr($c['name'],0,1))?></span><h2><?=esc($c['name'])?></h2><p><?=esc($c['email'])?></p><span class="account-status"><?=$c['verified']?'Email verified':'Email not yet verified'?></span><?php if(!$c['verified']):?><button class="button button-outline" data-customer-verify>Send verification email</button><?php endif;?><a class="text-link" href="/cart"><?=commerceIcon('cart')?> View my cart</a><button class="button button-outline" data-customer-logout>Sign out</button><div class="form-message" role="status"></div></aside><div class="account-bookings"><div class="account-heading"><div><span class="eyebrow">Your journeys</span><h2>My bookings <span><?=count($bookings)?></span></h2></div></div><?php if(!$bookings):?><div class="account-empty"><span><?=commerceIcon('cart')?></span><h3>Your next story is waiting.</h3><p>Bookings made while signed in appear here after successful payment. Guest bookings made without an account are not automatically linked by email.</p><a class="button" href="/tours">Explore experiences <?=icon()?></a></div><?php endif;foreach($bookings as $b):?><article class="customer-booking"><div class="customer-booking-top"><span><?=esc($b['reference'])?></span><span class="status-pill status-<?=esc($b['status'])?>"><?=esc(ucfirst($b['status']))?></span></div><h3><?=esc($b['tourTitle'])?></h3><div class="customer-booking-meta"><span><?=icon('calendar')?><?=esc($b['date'])?></span><span>Paid <?=money($b['total'])?></span></div><p class="muted"><?=$b['status']==='pending'?'Payment received. Your tour arrangements await team confirmation.':($b['status']==='confirmed'?'Your tour arrangements have been confirmed.':'The tour was cancelled. Contact our team about any applicable refund; cancellation does not automatically refund payment.')?></p><details><summary>View booking details</summary><div class="customer-booking-details"><?php foreach($b['items']??[$b] as $item):?><div><h4><?=esc($item['tourTitle'])?></h4><p><?=esc($item['date'])?> · <?=esc($item['adults']+$item['children'])?> guests · <?=money($item['total'])?></p><?php foreach($item['addons']??[] as $a):?><p><?=esc($a['title'])?> × <?=esc($a['quantity'])?> · <?=money($a['amount'])?></p><?php endforeach;?></div><?php endforeach;?><p>Guest: <?=esc($b['name'])?></p><?php if(!empty($b['pickup'])):?><p>Pickup: <?=esc($b['pickup'])?></p><?php endif;?><a class="text-link" href="/contact?subject=booking">Ask about this booking <?=icon()?></a></div></details></article><?php endforeach;?></div></section><?php renderPage('My bookings | Desert Sky Tourism','View your paid Desert Sky bookings and tour status.',ob_get_clean(),[],true);exit;}
if($path==='/cart'){$rows=cartRows();$total=array_sum(array_map(fn($r)=>$r['quote']['total']??0,$rows));$invalid=count(array_filter($rows,fn($r)=>!$r['available']));ob_start();echo pageHeader('Your next adventure','A cart full of possibilities.','Choose your experiences, review the details and make it a trip to remember.');?><section class="container section cart-layout"><div><div class="cart-heading"><h2>Your experiences <span><?=count($rows)?></span></h2><a class="text-link" href="/tours">Keep exploring <?=icon()?></a></div><?php if(isset($_GET['cancelled'])):?><div class="notice">Payment was cancelled. Your cart is saved and no paid booking was created.</div><?php endif;if(!$rows):?><div class="account-empty"><span><?=commerceIcon('cart')?></span><h3>Make room for a little adventure.</h3><p>Your cart is waiting for your favourite experiences.</p><a class="button" href="/tours">Explore tours <?=icon()?></a></div><?php endif;foreach($rows as $row):?><article class="cart-item"><img src="<?=esc($row['image'])?>" width="320" height="240" alt="<?=esc($row['title'])?>"><div><h3><?=esc($row['title'])?></h3><p><?=esc($row['input']['date'])?> · <?=esc($row['input']['adults']+$row['input']['children'])?> guests</p><?php foreach($row['quote']['addons']??[] as $a):?><small><?=esc($a['title'])?> × <?=esc($a['quantity'])?></small><?php endforeach;if(!$row['available']):?><p class="error">This experience or date is no longer available. Please remove it.</p><?php endif;?><button type="button" class="cart-remove" data-cart-remove="<?=esc($row['id'])?>">Remove experience</button></div><strong><?=$row['available']?money($row['quote']['total']):'Unavailable'?></strong></article><?php endforeach;?><div class="form-message" id="cart-message" role="status"></div></div><?php if($rows):?><aside class="cart-checkout form-panel"><span class="eyebrow">The next step</span><h2>Make it happen.</h2><div class="summary-total"><span>Order total</span><strong><?=money($total)?></strong></div><p>All